  constructor(brand) {
    this.brand = brand;
  }

  play() {
    return `${this.brand} instrument is making a sound.`;
  }
}

class Guitar extends Instrument {
  constructor(brand, strings) {
    super(brand);
    // Only store what is absolutely necessary for the instance
    this.strings = strings; 
  }

  play() {
    // 1. No dead code paths
    // 2. No temporary variable allocations
    // 3. Direct template literal return for maximum string evaluation speed
    return `${this.brand} guitar with ${this.strings} strings is strumming a vibrant melody!`;
  }
}

// --- Usage ---
const myGuitar = new Guitar("Fender", 6);
console.log(myGuitar.play()); 
// Output: Fender guitar with 6 strings is strumming a vibrant melody!
```

